# -*- coding: utf8 -*-import socketfrom lib.utility.util import chessboardfrom GUI.kv import new_playerdef change_ip_address(new_address):    ip_address_server = new_addressclient_s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)msg_client = bytes(str(chessboard) + str(new_player.who_is_playing), 'utf-8')ip_address_server = "192.168.1.40"client_s.sendto(msg_client, (ip_address_server, 12345))data, addr = client_s.recvfrom(4096)new_player.who_is_playing = int(data[len(data) - 1])temp = ""for value in range(len(data) - 1):    temp += valuechessboard = tempprint('srv says')print(str(data))client_s.close()